/* 蓝色系（标识符、命令、信息） */
.xterm-rows .xterm-fg-4 { color: #60a5fa !important; } /* 明亮天蓝，消除暗沉发黑 */
.xterm-rows .xterm-fg-12 { color: #93c5fd !important; } /* 高亮浅蓝 */

/* 洋红/紫色系（特殊关键字、转义符） */
.xterm-rows .xterm-fg-5 { color: #c084fc !important; } /* 明亮紫罗兰 */
.xterm-rows .xterm-fg-13 { color: #e879f9 !important; } /* 高亮洋红/粉紫 */

/* 青色系（字符串、属性、分隔线） */
.xterm-rows .xterm-fg-6 { color: #38bdf8 !important; } /* 明亮蔚蓝/青，字符串与重要参数 */
.xterm-rows .xterm-fg-14 { color: #67e8f9 !important; } /* 高亮浅青，分割线与重点标记 */

/* 暗淡/次要文字与注释（保持暗淡区分感，但透亮不发黑） */
.xterm-rows .xterm-fg-8,
.xterm-rows .xterm-dim {
    color: rgba(255, 255, 255, 0.65) !important;
}

/* 终端顶栏与次级标签（如“终端会话 Project ∨”、“历史对话”等）明度提升至 85% */
[data-testid*="terminal"] [class*="text-muted"],
[data-testid*="terminal"] [class*="text-secondary"],
[data-testid*="terminal-group"] [class*="text-muted"] {
