}

/* 最后一个表头单元格移除右边框 */
div[data-testid="conversation-view"] thead th:last-child,
div[data-testid="conversation-view"] th:last-child {
    border-right: none !important;
}

/* 5. 数据行 td 与 tbody 样式 */
